"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[31597],{72817:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>r,contentTitle:()=>a,default:()=>c,frontMatter:()=>i,metadata:()=>o,toc:()=>d});var h=n(31085),s=n(71184);const i={sidebar_position:21,slug:"/bible/Matthew/Matthew_21",title:"Matthew 21",hide_table_of_contents:!0},a="Matthew",o={id:"bible/Matthew/Matthew 21",title:"Matthew 21",description:"Chapter 21",source:"@site/docs/bible/Matthew/Matthew 21.md",sourceDirName:"bible/Matthew",slug:"/bible/Matthew/Matthew_21",permalink:"/bibleNotes/docs/bible/Matthew/Matthew_21",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Matthew/Matthew 21.md",tags:[],version:"current",sidebarPosition:21,frontMatter:{sidebar_position:21,slug:"/bible/Matthew/Matthew_21",title:"Matthew 21",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Matthew 20",permalink:"/bibleNotes/docs/bible/Matthew/Matthew_20"},next:{title:"Matthew 22",permalink:"/bibleNotes/docs/bible/Matthew/Matthew_22"}},r={},d=[{value:"Chapter 21",id:"chapter-21",level:2}];function l(e){const t={h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,h.jsxs)(h.Fragment,{children:[(0,h.jsx)(t.h1,{id:"matthew",children:"Matthew"}),"\n",(0,h.jsx)(t.h2,{id:"chapter-21",children:"Chapter 21"}),"\n",(0,h.jsx)(t.p,{children:"Christ rides into Jerusalem upon an ass.  He casts the buyers and sellers out of the temple, curses the fig tree and puts to silence the priests and scribes."}),"\n",(0,h.jsx)(n,{verse:1,children:"And when they drew nigh to Jerusalem and were come to Bethphage, unto mount Olivet, then Jesus sent two disciples,"}),"\n",(0,h.jsx)(n,{verse:2,children:"Saying to them: Go ye into the village that is over against you: and immediately you shall find an ass tied and a colt with her. Loose them and bring them to me."}),"\n",(0,h.jsx)(n,{verse:3,children:"And if any man shall say anything to you, say ye that the Lord hath need of them. And forthwith he will let them go."}),"\n",(0,h.jsx)(n,{verse:4,children:"Now all this was done that it might be fulfilled which was spoken by the prophet, saying:"}),"\n",(0,h.jsx)(n,{verse:5,children:"Tell ye the daughter of Sion: Behold thy king cometh to thee, meek and sitting upon an ass and a colt, the foal of her that is used to the yoke."}),"\n",(0,h.jsx)(n,{verse:6,children:"And the disciples going, did as Jesus commanded them."}),"\n",(0,h.jsx)(n,{verse:7,children:"And they brought the ass and the colt and laid their garments upon them and made him sit thereon."}),"\n",(0,h.jsx)(n,{verse:8,children:"And a very great multitude spread their garments in the way: and others cut boughs from the trees and strewed them in the way."}),"\n",(0,h.jsx)(n,{verse:9,children:"And the multitudes that went before and that followed cried, saying: Hosanna to the son of David: Blessed is he that cometh in the name of the Lord: Hosanna in the highest."}),"\n",(0,h.jsx)(n,{verse:10,children:"And when he was come into Jerusalem, the whole city was moved, saying: Who is this?"}),"\n",(0,h.jsx)(n,{verse:11,children:"And the people said: This is Jesus, the prophet from Nazareth of Galilee."}),"\n",(0,h.jsx)(n,{verse:12,children:"And Jesus went into the temple of God and cast out all them that sold and bought in the temple and overthrew the tables of the money changers and the chairs of them that sold doves."}),"\n",(0,h.jsx)(n,{verse:13,children:"And he saith to them: It is written, My house shall be called the house of prayer; but you have made it a den of thieves."}),"\n",(0,h.jsx)(n,{verse:14,children:"And there came to him the blind and the lame in the temple: and he healed them."}),"\n",(0,h.jsx)(n,{verse:15,children:"And the chief priests and scribes, seeing the wonderful things that he did and the children crying in the temple and saying: Hosanna to the son of David, were moved with indignation,"}),"\n",(0,h.jsx)(n,{verse:16,children:"And said to him: Hearest thou what these say? And Jesus said to them: Yea, have you never read: Out of the mouth of infants and of sucklings thou hast perfected praise?"}),"\n",(0,h.jsx)(n,{verse:17,children:"And leaving them, he went out of the city into Bethania and remained there."}),"\n",(0,h.jsx)(n,{verse:18,children:"And in the morning, returning into the city, he was hungry."}),"\n",(0,h.jsx)(n,{verse:19,children:"And seeing a certain fig tree by the way side, he came to it and found nothing on it but leaves only. And he saith to it: May no fruit grow on thee henceforward for ever. And immediately the fig tree withered away."}),"\n",(0,h.jsx)(n,{verse:20,children:"And the disciples seeing it wondered, saying: How is it presently withered away?"}),"\n",(0,h.jsx)(n,{verse:21,children:"And Jesus answering, said to them: Amen, I say to you, if you shall have faith and stagger not, not only this of the fig tree shall you do, but also if you shall say to this mountain, Take up and cast thyself into the sea, it shall be done."}),"\n",(0,h.jsx)(n,{verse:22,children:"And all things whatsoever you shall ask in prayer believing, you shall receive."}),"\n",(0,h.jsx)(n,{verse:23,children:"And when he was come into the temple, there came to him, as he was teaching, the chief priests and ancients of the people, saying: By what authority dost thou these things? And who hath given thee this authority?"}),"\n",(0,h.jsx)(n,{verse:24,children:"Jesus answering, said to them: I also will ask you one word, which if you shall tell me, I will also tell you by what authority I do these things."}),"\n",(0,h.jsx)(n,{verse:25,children:"The baptism of John, whence was it? From heaven or from men? But they thought within themselves, saying:"}),"\n",(0,h.jsx)(n,{verse:26,children:"If we shall say, from heaven, he will say to us: Why then did you not believe him? But if we shall say, from men, we are afraid of the multitude: for all held John as a prophet."}),"\n",(0,h.jsx)(n,{verse:27,children:"And answering Jesus, they said: We know not. He also said to them: Neither do I tell you by what authority I do these things."}),"\n",(0,h.jsx)(n,{verse:28,children:"But what think you? A certain man had two sons: and coming to the first, he said: Son, go work to day in my vineyard."}),"\n",(0,h.jsx)(n,{verse:29,children:"And he answering, said: I will not. But afterwards, being moved with repentance, he went."}),"\n",(0,h.jsx)(n,{verse:30,children:"And coming to the other, he said in like manner. And he answering said: I go, Sir. And he went not."}),"\n",(0,h.jsx)(n,{verse:31,children:"Which of the two did the father's will? They say to him: The first. Jesus saith to them: Amen I say to you that the publicans and the harlots shall go into the kingdom of God before you."}),"\n",(0,h.jsx)(n,{verse:32,children:"For John came to you in the way of justice: and you did not believe him. But the publicans and the harlots believed him: but you, seeing it, did not even afterwards repent, that you might believe him."}),"\n",(0,h.jsx)(n,{verse:33,children:"Hear ye another parable. There was a man, an householder, who planted a vineyard and made a hedge round about it and dug in it a press and built a tower and let it out to husbandmen and went into a strange country."}),"\n",(0,h.jsx)(n,{verse:34,children:"And when the time of the fruits drew nigh, he sent his servants to the husbandmen that they might receive the fruits thereof."}),"\n",(0,h.jsx)(n,{verse:35,children:"And the husbandmen laying hands on his servants, beat one and killed another and stoned another."}),"\n",(0,h.jsx)(n,{verse:36,children:"Again he sent other servants, more than the former; and they did to them in like manner."}),"\n",(0,h.jsx)(n,{verse:37,children:"And last of all he sent to them his son, saying: They will reverence my son."}),"\n",(0,h.jsx)(n,{verse:38,children:"But the husbandmen seeing the son, said among themselves: This is the heir: come, let us kill him, and we shall have his inheritance."}),"\n",(0,h.jsx)(n,{verse:39,children:"And taking him, they cast him forth out of the vineyard and killed him."}),"\n",(0,h.jsx)(n,{verse:40,children:"When therefore the lord of the vineyard shall come, what will he do to those husbandmen?"}),"\n",(0,h.jsx)(n,{verse:41,children:"They say to him: He will bring those evil men to an evil end and let out his vineyard to other husbandmen that shall render him the fruit in due season."}),"\n",(0,h.jsx)(n,{verse:42,children:"Jesus saith to them: Have you never read in the Scriptures: The stone which the builders rejected, the same is become the head of the corner? By the Lord this has been done; and it is wonderful in our eyes."}),"\n",(0,h.jsx)(n,{verse:43,children:"Therefore I say to you that the kingdom of God shall be taken from you and shall be given to a nation yielding the fruits thereof."}),"\n",(0,h.jsx)(n,{verse:44,children:"And whosoever shall fall on this stone shall be broken: but on whomsoever it shall fall, it shall grind him to powder."}),"\n",(0,h.jsx)(n,{verse:45,children:"And when the chief priests and Pharisees had heard his parables, they knew that he spoke of them."}),"\n",(0,h.jsx)(n,{verse:46,children:"And seeking to lay hands on him, they feared the multitudes, because they held him as a prophet."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,h.jsx)(t,{...e,children:(0,h.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>a,x:()=>o});var h=n(14041);const s={},i=h.createContext(s);function a(e){const t=h.useContext(i);return h.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),h.createElement(i.Provider,{value:t},e.children)}}}]);